def close(self) -> None:
    # Close the underlying connection first to interrupt any concurrent
    # blocking read on another thread. Closing the file-like object first
    # can hang if it attempts to drain remaining bytes.
    # Debug prints for local harness
    print("HTTPResponse.close: start")
    try:
        if self._connection:
            try:
                print("HTTPResponse.close: closing connection")
                self._connection.close()
            except Exception as e:
                print("HTTPResponse.close: connection close error:", e)
                # Best-effort close; suppress to avoid masking original errors
                pass
        # Also close the original httplib response to ensure its internal
        # file object is torn down and won't attempt to drain remaining data.
        if self._original_response is not None:
            try:
                print("HTTPResponse.close: closing original_response")
                self._original_response.close()
            except Exception as e:
                print("HTTPResponse.close: original_response close error:", e)
                pass
        # Finally close the file-like object if present.
        if self._fp and not self.closed:
            try:
                print("HTTPResponse.close: closing _fp")
                self._fp.close()
            except Exception as e:
                print("HTTPResponse.close: _fp close error:", e)
                pass
    finally:
        # Ensure we mark the response as closed.
        self._fp = None
        if not self.auto_close:
            try:
                io.IOBase.close(self)
            except Exception:
                pass
        print("HTTPResponse.close: end")

